"""Robustness probes generated by API Shakedown. The cases live in robustness_cases.json.

Each probe sends a malformed request; a robust server rejects it with a 4xx, never a 5xx.
Point SHAKEDOWN_TARGET_URL at a real server. Against the stubs (SHAKEDOWN_SELECT_STATUS=1)
probes request the operation's documented 4xx, and are skipped if it has none.

Configuration: see shakedown_support.py. Requires pytest and httpx.
"""

from collections.abc import Iterator
from typing import Any

import httpx
import pytest
from shakedown_support import SELECT_STATUS, TIMEOUT, build_request, load_cases, target_url

DATA = load_cases(__file__, "robustness_cases.json")


@pytest.fixture(scope="module")
def client() -> Iterator[httpx.Client]:
    with httpx.Client(base_url=target_url(DATA), timeout=TIMEOUT) as session:
        yield session


@pytest.mark.parametrize("case", DATA["cases"], ids=[c["id"] for c in DATA["cases"]])
def test_rejects_malformed_request(client: httpx.Client, case: dict[str, Any]) -> None:
    if SELECT_STATUS and not case["stub_status"]:
        pytest.skip("the operation documents no 4xx response for the stubs to return")
    response = client.request(**build_request(case, DATA["status_header"], case["stub_status"]))
    where = f"{case['method'].upper()} {response.request.url} ({case['description']})"
    assert response.status_code < 500, (
        f"{where}: server error {response.status_code}. Body: {response.text[:500]}"
    )
    assert 400 <= response.status_code < 500, (
        f"{where}: expected a 4xx rejection, got {response.status_code}."
    )
